    /// <summary>Wait until a condition variable is signaled.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_WaitCondition</c>.</para>
    /// <para>
    /// This function unlocks the specified <c>mutex</c> and waits for another thread to call SDL_SignalCondition() or
    /// SDL_BroadcastCondition() on the condition variable <c>cond</c>. Once the condition variable is signaled, the
    /// mutex is re-locked and the function returns.
    /// </para>
    /// <para>
    /// The mutex must be locked before calling this function. Locking the mutex recursively (more than once) is not
    /// supported and leads to undefined behavior.
    /// </para>
    /// <para>This function is the equivalent of calling SDL_WaitConditionTimeout() with a time length of -1.</para>
    /// <para>Thread safety: It is safe to call this function from any thread.</para>
    /// <para>This function is available since SDL 3.2.0.</para>
    /// <para>
    /// See also: <c>SDL_BroadcastCondition</c>, <c>SDL_SignalCondition</c>, <c>SDL_WaitConditionTimeout</c>.
    /// </para>
    /// </remarks>
    /// <param name="cond">the condition variable to wait on.</param>
    /// <param name="mutex">the mutex used to coordinate thread access.</param>
    [LibraryImport("jade_native", EntryPoint = "SDL_WaitCondition")]
    [UnmanagedCallConv(CallConvs = [typeof(CallConvCdecl)])]
