    /// <summary>Wait until a condition variable is signaled or a certain time has passed.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_WaitConditionTimeout</c>.</para>
    /// <para>
    /// This function unlocks the specified <c>mutex</c> and waits for another thread to call SDL_SignalCondition() or
    /// SDL_BroadcastCondition() on the condition variable <c>cond</c>, or for the specified time to elapse. Once the
    /// condition variable is signaled or the time elapsed, the mutex is re-locked and the function returns.
    /// </para>
    /// <para>
    /// The mutex must be locked before calling this function. Locking the mutex recursively (more than once) is not
    /// supported and leads to undefined behavior.
    /// </para>
    /// <para>Thread safety: It is safe to call this function from any thread.</para>
    /// <para>This function is available since SDL 3.2.0.</para>
    /// <para>See also: <c>SDL_BroadcastCondition</c>, <c>SDL_SignalCondition</c>, <c>SDL_WaitCondition</c>.</para>
    /// </remarks>
    /// <param name="cond">the condition variable to wait on.</param>
    /// <param name="mutex">the mutex used to coordinate thread access.</param>
    /// <param name="timeoutMS">the maximum time to wait, in milliseconds, or -1 to wait indefinitely.</param>
    /// <returns>
    /// true if the condition variable is signaled, false if the condition is not signaled in the allotted time.
    /// </returns>
    [LibraryImport("jade_native", EntryPoint = "SDL_WaitConditionTimeout")]
